import { describe, expect, it } from 'vitest';
import { parseChordPro } from '../../src/core/chordpro';
import { importSong } from '../../src/core/import';
import { extractPdfText } from '../../src/core/pdf';
import { loadFixtureBuffer } from '../helpers/fixtures';
import { squeeze } from '../helpers/text';

/**
 * Committed PDF fixtures generated by `node scripts/make-pdf-fixtures.mjs`.
 * They cover the coordinate reconstruction paths with invented content.
 */

const readPdf = async (name: string) => extractPdfText(loadFixtureBuffer(`generated/${name}`));


describe('generated PDF fixtures', () => {
  it('extracts a single-column chord sheet and imports it', async () => {
    const extracted = await readPdf('generated-single-column.pdf');
    expect(extracted.pages).toBe(1);
    expect(extracted.hasText).toBe(true);
    expect(squeeze(extracted.text)).toContain('Walking down the empty road');

    const result = importSong(extracted.text);
    const doc = parseChordPro(result.chordpro);
    expect(doc.title).toBe('Generated Song');
    expect(doc.subtitle).toBe('The Test Band');
    expect(doc.capo).toBe(2);
    expect(result.stats.merged).toBeGreaterThan(0);
    expect(result.chordpro).toContain('[Am]');
  });

  it('reads two columns left to right', async () => {
    const extracted = await readPdf('generated-two-columns.pdf');
    expect(extracted.hasText).toBe(true);

    const text = squeeze(extracted.text);
    const first = text.indexOf('number 1');
    const last = text.indexOf('number 8');
    expect(first).toBeGreaterThanOrEqual(0);
    expect(last).toBeGreaterThan(first);

    const result = importSong(extracted.text);
    expect(result.stats.merged).toBeGreaterThanOrEqual(8);
  });

  it('drops pagination and decorative noise', async () => {
    const extracted = await readPdf('generated-noise.pdf');
    expect(squeeze(extracted.text)).toContain('Page 1/2');

    const result = importSong(extracted.text);
    expect(result.chordpro).not.toMatch(/^Page \d+\s*\/\s*\d+$/m);
    expect(result.chordpro).not.toMatch(/^[—–_=*·•-]{3,}$/m);
    const lyrics = result.chordpro.replace(/\[[^\]]*\]/g, '');
    expect(lyrics).toContain('This line survives the noise filter');
  });

  it('aligns chords on oddly spaced lines', async () => {
    const extracted = await readPdf('generated-misaligned.pdf');
    const result = importSong(extracted.text);

    expect(result.stats.merged).toBeGreaterThan(0);
    expect(result.chordpro).toContain('{comment: (2x)}');
    expect(result.chordpro).toContain('[Am]');
  });

  it('reports a scanned page without a text layer', async () => {
    const extracted = await readPdf('generated-scan.pdf');
    expect(extracted.hasText).toBe(false);
    expect(extracted.text).toBe('');
  });
});
